    local completed_masked_carnivale_byte = completed_masked_carnivale_tvbr:le_uint()
    for completed_masked_carnivale_bit = 0, 7 do
      if math.floor(completed_masked_carnivale_byte / 2 ^ completed_masked_carnivale_bit) % 2 == 1 then
        local completed_masked_carnivale_val = (completed_masked_carnivale_pos - 464) * 8 + completed_masked_carnivale_bit
        tree:add_le(player_setup_content_fields.completed_masked_carnivale, completed_masked_carnivale_tvbr, completed_masked_carnivale_val)
      end
    end
  end

  -- dissect the completed_vvd_notebook_contents field
  for completed_vvd_notebook_contents_pos = 468, 475 - 1 do
    local completed_vvd_notebook_contents_tvbr = tvbuf:range(completed_vvd_notebook_contents_pos, 1)
    local completed_vvd_notebook_contents_byte = completed_vvd_notebook_contents_tvbr:le_uint()
    for completed_vvd_notebook_contents_bit = 0, 7 do
      if math.floor(completed_vvd_notebook_contents_byte / 2 ^ completed_vvd_notebook_contents_bit) % 2 == 1 then
        local completed_vvd_notebook_contents_val = (completed_vvd_notebook_contents_pos - 468) * 8 + completed_vvd_notebook_contents_bit
        tree:add_le(player_setup_content_fields.completed_vvd_notebook_contents, completed_vvd_notebook_contents_tvbr, completed_vvd_notebook_contents_val)
      end
    end
  end

  -- dissect the unlocked_misc_content field
  for unlocked_misc_content_pos = 475, 480 - 1 do
    local unlocked_misc_content_tvbr = tvbuf:range(unlocked_misc_content_pos, 1)
    local unlocked_misc_content_byte = unlocked_misc_content_tvbr:le_uint()
    for unlocked_misc_content_bit = 0, 7 do
      if math.floor(unlocked_misc_content_byte / 2 ^ unlocked_misc_content_bit) % 2 == 1 then
        local unlocked_misc_content_val = (unlocked_misc_content_pos - 475) * 8 + unlocked_misc_content_bit
        tree:add_le(player_setup_content_fields.unlocked_misc_content, unlocked_misc_content_tvbr, unlocked_misc_content_val)
      end
    end
  end

  -- dissect the completed_misc_content field
  for completed_misc_content_pos = 480, 485 - 1 do
    local completed_misc_content_tvbr = tvbuf:range(completed_misc_content_pos, 1)
    local completed_misc_content_byte = completed_misc_content_tvbr:le_uint()
    for completed_misc_content_bit = 0, 7 do
      if math.floor(completed_misc_content_byte / 2 ^ completed_misc_content_bit) % 2 == 1 then
        local completed_misc_content_val = (completed_misc_content_pos - 480) * 8 + completed_misc_content_bit
        tree:add_le(player_setup_content_fields.completed_misc_content, completed_misc_content_tvbr, completed_misc_content_val)
      end
    end
  end

  return len
end
